with t as (
 select lu.id learning_unit_id,(select max(v.version_number)+1 from public.learning_unit_versions v where v.learning_unit_id=lu.id) target_version,(select v.content from public.learning_unit_versions v where v.learning_unit_id=lu.id order by v.version_number desc limit 1) old_content
 from public.learning_units lu where lu.stable_key='fondamenti:emergenze-figure'
), e as (
 select learning_unit_id,target_version,old_content||jsonb_build_object(
 'summary','Nelle emergenze aziendali ruoli, segnali e comunicazioni devono essere chiari prima dell’evento.','detail','L’unità distingue responsabilità organizzative, addetti antincendio, addetti al primo soccorso, lavoratori e soggetti incaricati dal piano aziendale. Il punto non è creare un capo dell’emergenza generico, ma applicare il piano reale, evitare sovrapposizioni e garantire allarme, evacuazione, assistenza e handover.','focus','Coordinare persone e funzioni senza sostituire competenze o ruoli non previsti dal piano aziendale.','case','Scatta un allarme: c’è fumo in un’area, una persona riferisce un malore e un visitatore non conosce le vie di uscita. Ricostruire chi fa cosa nei primi minuti.','question','Perché durante un’emergenza non è corretto che chi arriva per primo assuma automaticamente tutte le funzioni?','question_explanation','Perché le funzioni dipendono da designazioni, formazione e piano aziendale. Occorre attivare le persone previste e non svolgere compiti tecnici o sanitari per i quali non si è formati.','common_errors',jsonb_build_array('Confondere addetto antincendio e addetto al primo soccorso.','Inventare ruoli di coordinamento non previsti dal piano.','Rientrare in area pericolosa senza ruolo e condizioni adeguate.','Dimenticare visitatori o persone con esigenze speciali.','Chiamare i soccorsi senza fornire accesso e informazioni aggiornate.'),'teacher_activity',jsonb_build_object('prompt','Usare il caso fumo + malore + visitatore e assegnare ai gruppi ruoli diversi.','method','Role mapping su planimetria e scenario temporizzato.','debrief','Verificare copertura funzioni, messaggi, assistenza e handover.'),'operational',jsonb_build_object('before',jsonb_build_array('Conosci segnali, vie di esodo, punto di raccolta e procedura di chiamata.','Conosci funzioni designate e sostituzioni previste.','Individua chi può aver bisogno di assistenza.'),'during',jsonb_build_array('Attiva allarme e comunicazioni previste.','Segui il ruolo assegnato.','Mantieni libere le vie di esodo.','Aggiorna il referente e i soccorsi se cambia la situazione.'),'after',jsonb_build_array('Conferma esito evacuazione secondo procedura.','Consegna informazioni ai soccorsi esterni.','Partecipa a debriefing e segnala criticità.'),'if_problem',jsonb_build_array('Non entrare in area non sicura senza ruolo e competenza.','Se una funzione è scoperta, attiva la sostituzione prevista.','Se manca una persona all’appello, segnala: non improvvisare ricerche in area non sicura.'),'who_to_involve',jsonb_build_array('Addetti antincendio','Addetti al primo soccorso','Figure previste dal piano','Preposto/dirigente/datore','Soccorsi esterni'),'stop_conditions',jsonb_build_array('Area non accessibile in sicurezza.','Compito oltre formazione/competenza.','Ordine di evacuazione o indicazione dei soccorsi incompatibile con la prosecuzione.'),'adaptation','Usare ruoli, numeri, segnali, vie di esodo e punti di raccolta reali dell’azienda.'),'scope_boundary','Percorso aziendale interno non certificante. Non sostituisce formazione antincendio/primo soccorso né le prove previste dal piano.','drill_reference',jsonb_build_object('company_drill_separate',true,'outside_nominal_course_minutes',true,'completed_digitally',false),'formative_check',jsonb_build_object('question','Come eviti sovrapposizioni tra ruoli in uno scenario incendio + infortunato?','explanation','Attivi il piano, distingui le funzioni e ciascun addetto opera entro formazione e compiti assegnati.','formative_only',true,'test_builder_excluded',true),'graphic_cards',jsonb_build_array(jsonb_build_object('title','ALLARME','body','Segnale chiaro e procedura nota.'),jsonb_build_object('title','RUOLI','body','Funzioni coordinate ma distinte.'),jsonb_build_object('title','ESODO','body','Vie libere, assistenza, punto di raccolta.'),jsonb_build_object('title','HANDOVER','body','Ai soccorsi servono accesso, rischi e persone coinvolte.')),'didactic_version','emergency-authored-v3','source_keys',jsonb_build_array('normattiva-dlgs81-vigente','gu-dm2-2021-antincendio','vvf-materiali-antincendio','inail-primo-soccorso-2018'),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16'),'quality',coalesce(old_content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true,'scope_boundary_explicit',true),'final_assessment',false,'test_builder_excluded',true) content
 from t
), f as (
 select e.*,content||jsonb_build_object('evidence_sources',(select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(content->'source_keys') sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key)) final_content from e
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,target_version,'draft',final_content,md5(final_content::text),null from f
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

with target as (
 select lu.id learning_unit_id,lu.stable_key,lu.title,(select max(v.version_number)+1 from public.learning_unit_versions v where v.learning_unit_id=lu.id) target_version,(select v.content from public.learning_unit_versions v where v.learning_unit_id=lu.id order by v.version_number desc limit 1) old_content
 from public.learning_units lu where lu.stable_key like 'height:%'
), prof as (
 select t.*,
 case stable_key when 'height:hierarchy' then 'Partire dall’eliminazione/riduzione dell’esposizione e dalla protezione collettiva. Il DPI anticaduta è misura per il rischio residuo.' when 'height:systems' then 'Distinguere trattenuta, posizionamento e arresto caduta: obiettivo, componenti, ancoraggio e conseguenze sono diversi.' when 'height:inspection' then 'Prima dell’uso identificare DPI/componenti, verificarne compatibilità e condizioni; un componente dubbio va tolto dal servizio.' when 'height:anchors-clearance' then 'Ancoraggio, posizione, tirante d’aria e pendolo vanno valutati insieme prima del collegamento.' when 'height:donning' then 'Indossare e regolare l’imbracatura secondo istruzioni e addestramento, verificando punti di attacco, chiusure e compatibilità.' when 'height:movement' then 'Pianificare transizioni e movimento mantenendo il livello di protezione previsto, senza fasi non protette improvvisate.' when 'height:work-scenario' then 'Integrare accesso, area sottostante, caduta oggetti, meteo, interferenze, utensili e chiusura del lavoro.' when 'height:rescue' then 'Prima dell’accesso deve esistere una risposta credibile a caduta, sospensione o impossibilità di rientro; nessun recupero improvvisato.' end focus,
 case stable_key when 'height:hierarchy' then 'Manutenzione in quota: è disponibile una piattaforma protetta ma richiede più tempo di allestimento rispetto al solo DPI. Motivare la scelta.' when 'height:systems' then 'Su una copertura quasi tutto il lavoro avviene lontano dal bordo, ma una fase richiede avvicinamento. Scegliere la configurazione corretta.' when 'height:inspection' then 'Nel controllo pre-uso trovi una cucitura sospetta e una marcatura poco leggibile. Decidere cosa fare.' when 'height:anchors-clearance' then 'Il punto di ancoraggio è laterale e basso; sotto c’è una struttura. Stabilire quali dati servono prima del GO.' when 'height:donning' then 'Imbracatura molto lasca e collegamento a punto non previsto dal fabbricante. Individuare errori e correzioni.' when 'height:movement' then 'Per superare un ostacolo occorre passare da un tratto di linea a un altro. Descrivere transizione e STOP.' when 'height:work-scenario' then 'Copertura con vento in aumento, persone sotto e utensili portatili. Costruire sequenza completa e almeno tre STOP.' when 'height:rescue' then 'Operatore sospeso dopo arresto caduta e incapace di rientrare. Spiegare cosa doveva essere previsto prima.' end case_text,
 jsonb_build_array('normattiva-dlgs81-vigente','eurlex-reg-2016-425','inail-ancoraggi-cadute','inail-quaderni-cantieri','inail-tutorial-cadute-2022') source_keys
 from target t
), enriched as (
 select p.*,old_content||jsonb_build_object('summary',coalesce(old_content->>'summary',focus),'detail',coalesce(old_content->>'detail','')||case when coalesce(old_content->>'detail','')<>'' then ' ' else '' end||focus||' Il percorso SafetyManager è strutturato su 8 ore per scelta di catalogo; non è dichiarata una durata minima nazionale di 8 ore.','focus',focus,'case',case_text,'question','Quale decisione deve essere presa prima di procedere nel caso “'||title||'”?','question_explanation','La risposta deve dimostrare una decisione GO/NO-GO basata su protezione collettiva, sistema scelto, istruzioni, compatibilità, area sottostante e piano di emergenza.','common_errors',jsonb_build_array('Usare il DPI come prima scelta senza valutare misure collettive.','Confondere trattenuta, posizionamento e arresto caduta.','Considerare qualunque punto robusto un ancoraggio idoneo.','Ignorare tirante d’aria, ostacoli e pendolo.','Usare componenti danneggiati/non compatibili.','Iniziare senza piano di recupero attuabile.'),'teacher_activity',jsonb_build_object('prompt',case_text,'method',case when stable_key in ('height:inspection','height:donning','height:movement','height:work-scenario','height:rescue') then 'Dimostrazione/addestramento in presenza con prova guidata, correzione e ripetizione.' else 'Analisi scenario e decisione GO/NO-GO prima della dimostrazione/addestramento in presenza.' end,'debrief','Far verbalizzare misura scelta, limiti, STOP e recupero.'),'operational',jsonb_build_object('before',jsonb_build_array('Valuta se evitare il lavoro o usare protezione collettiva/attrezzatura più sicura.','Definisci accesso, sistema, ancoraggi e percorso.','Controlla DPI, compatibilità e condizioni pre-uso.','Verifica tirante d’aria, ostacoli, pendolo, area sottostante, meteo e interferenze.','Conferma piano di recupero.'),'during',jsonb_build_array('Mantieni la configurazione prevista e addestrata.','Controlla cambiamenti di meteo/area/percorso.','Proteggi l’area sottostante.','Esegui transizioni solo come previsto dal sistema/addestramento.'),'after',jsonb_build_array('Rientra e disconnettiti in zona sicura.','Ispeziona e segnala anomalie.','Conserva secondo istruzioni.','Dopo una caduta o evento anomalo, sottrai i componenti dal servizio fino alla valutazione prevista.'),'if_problem',jsonb_build_array('STOP e mantieni/raggiungi una condizione sicura.','Non improvvisare ancoraggi, componenti o tecniche.','Attiva il recupero previsto.','Non riprendere fino a nuova valutazione.'),'who_to_involve',jsonb_build_array('Preposto/referente','Datore/RSPP','Persona competente/fornitore/manutenzione','Squadra prevista dal piano di recupero','Soccorsi esterni'),'stop_conditions',jsonb_build_array('Protezione collettiva necessaria ma assente/non idonea.','DPI/componente danneggiato, non identificabile o non compatibile.','Ancoraggio/tirante/percorso non verificabili.','Meteo/accesso/interferenze incompatibili.','Piano di recupero non attuabile.','Tecnica oltre l’addestramento ricevuto.'),'adaptation','Adattare a luogo, attività, DVR, sistema reale, istruzioni dei fabbricanti, ancoraggi e piano di recupero.'),'practical_reference',jsonb_build_object('required',true,'completed_digitally',false,'catalog_total_minutes',480,'catalog_duration_source','safetymanager_legacy_catalog','statutory_total_duration_claim',false,'internal_theory_minutes',240,'internal_practical_minutes',240,'internal_split_is_statutory_claim',false,'purpose','supporto alla formazione e all’addestramento in presenza'),'scope_boundary','Percorso SafetyManager di 8 ore con allocazione interna 4h teoria + 4h pratica; durata e split non sono presentati come minimo nazionale. Non sostituisce formazione funi o ponteggi.','formative_check',jsonb_build_object('question','Qual è la condizione decisiva per procedere in sicurezza?','explanation','Procedere solo quando misura scelta, sistema, componenti, area e recupero sono coerenti con valutazione dei rischi e addestramento.','formative_only',true,'test_builder_excluded',true),'graphic_cards',jsonb_build_array(jsonb_build_object('title','PRIMA COLLETTIVA','body','Privilegiare protezioni collettive.'),jsonb_build_object('title','SISTEMA','body','Trattenuta, posizionamento e arresto non sono equivalenti.'),jsonb_build_object('title','SPAZIO','body','Ancoraggio, tirante, ostacoli e pendolo decidono il GO.'),jsonb_build_object('title','RECUPERO','body','Il recupero va pianificato prima.')),'didactic_version','height-authored-v3','source_keys',source_keys,'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16'),'quality',coalesce(old_content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true,'practical_gate_explicit',true,'scope_boundary_explicit',true,'nonstatutory_duration_explicit',true),'final_assessment',false,'test_builder_excluded',true) new_content
 from prof p
), final_content as (
 select e.*,new_content||jsonb_build_object('evidence_sources',(select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key)) content_final from enriched e
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,target_version,'draft',content_final,md5(content_final::text),null from final_content
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

with authored as (
 select lu.id learning_unit_id,luv.content->'source_keys' source_keys,luv.content->>'didactic_version' dv
 from public.learning_units lu join public.learning_unit_versions luv on luv.learning_unit_id=lu.id
 where luv.status='draft' and luv.content->>'didactic_version' in ('emergency-authored-v3','height-authored-v3')
)
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select a.learning_unit_id,sk.source_key,'authored_evidence_v3','Fonte usata per validazione normativa e tecnica nella versione '||a.dv||'.',date '2026-10-16',jsonb_build_object('didactic_version',a.dv,'reuse_policy','reference_and_original_rewrite')
from authored a cross join lateral jsonb_array_elements_text(a.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;

do $$ declare h int;e int;links int;bad int;begin
 select count(*) into h from public.learning_unit_versions where content->>'didactic_version'='height-authored-v3' and status='draft';
 select count(*) into e from public.learning_unit_versions where content->>'didactic_version'='emergency-authored-v3' and status='draft';
 select count(*) into links from public.course_module_units cmu join public.learning_unit_versions luv on luv.id=cmu.unit_version_id where luv.content->>'didactic_version' in ('height-authored-v3','emergency-authored-v3');
 select count(*) into bad from public.learning_unit_versions where content->>'didactic_version'='height-authored-v3' and (content->'quality'->>'teacher_ready' is distinct from 'true' or content->'quality'->>'learner_ready' is distinct from 'true' or content->'quality'->>'question_has_explanation' is distinct from 'true' or content->'quality'->>'practical_gate_explicit' is distinct from 'true' or content->'quality'->>'nonstatutory_duration_explicit' is distinct from 'true');
 if h<>8 or e<>1 or links<>0 or bad<>0 then raise exception 'v20.080 assertions failed: height %, emergency %, links %, bad %',h,e,links,bad; end if;
end $$;
